from sympy import *
x, a, b, t = symbols('x a b t', real=True)
ok = lambda n, c: print("OK " if c else "BAD", n)
I = Interval
ok("28.10", simplify(sum(s for s in solveset(Eq(tan(x/2), sqrt(3)), x, I(-2*pi, 3*pi/2))) + 2*pi/3) == 0)
ok("35.9", diff(x*x**Rational(1, 4), x).subs(x, 256) == 5)
ok("22.3", simplify(cos(5*pi/9) + sin(pi/18)) == 0 and N(cos(5*pi/9) + cos(pi/18)) != 0)
f = x**3 + x**2 - 6*x + 1; T = f.subs(x, 1) + diff(f, x).subs(x, 1)*(x - 1); x0 = solve(T, x)[0]; ok("37.22", abs(x0*T.subs(x, 0))/2 == 2)
S = 2*t*(9 - t**2/2); tm = solve(diff(S, t), t); ok("40.18", max(S.subs(t, r) for r in tm if 0 <= r <= 3*sqrt(2)) == 12*sqrt(6))
ok("8.8", Rational(3, 10)*10000**Rational(1, 4) - 5*256**Rational(1, 8) + 6*(-6**Rational(1, 10))**10 == 29)
r = solveset(Eq(cos(x - pi/6), S.Half if False else Rational(1, 2)), x, I(-4*pi, 0)); ok("26.7", max(r) == -pi/6)
g = cos(x) + x/2; ok("39.19", solveset(diff(g, x) > 0, x, I(-7*pi/6, 5*pi/6)) == Union(I.open(-7*pi/6, pi/6)) and solveset(diff(g, x) < 0, x, I(-7*pi/6, 5*pi/6)) == I.open(pi/6, 5*pi/6))
ok("37.18", all(4*r**3 != 12*r - 10 for r in solve(12*x**2 - 12, x)))
pa, pb = symbols('pa pb', positive=True)
E = (pa**Rational(3, 2) + pb**Rational(3, 2))/(pa**2 - pa*pb)**Rational(2, 3) / (pa**Rational(2, 3)*(pa - pb)**Rational(1, 3)/(pa**Rational(3, 2) - pb**Rational(3, 2)))
ok("10.25(4)", all(abs(N((E - (pa**2 + pa*pb + pb**2)/pa**Rational(4, 3)).subs({pa: u, pb: v}))) < 1e-9 for u, v in [(5, 2), (Rational(7, 3), Rational(1, 5)), (9, 4)]))
y = 3*x**2 - 18*x + 2; ok("39.24", min(y.subs(x, v) for v in [4, 5]) == -22 and diff(y, x).subs(x, 4) > 0)
e = 4*sin(x)**2 + 9*cot(x)**2 - 6; ok("30.6(10)", simplify(e.subs(x, pi/3)) == 0 and simplify(e.subs(x, -pi/3)) == 0 and simplify(e.subs(x, pi/4)) != 0 and simplify(e.subs(x, 2*pi/3)) == 0)
h = (3*x + 1)/sqrt(x - 1); ok("39.23", solve(diff(h, x), x) == [Rational(7, 3)] and diff(h, x).subs(x, 2) < 0 and diff(h, x).subs(x, 3) > 0)
ok("26.12", solve(-a**2 - 1 + 1, a) == [0])
yy = tan(x)*sin(2*x + 5); ok("36.19(4)", simplify(diff(yy, x) - (sin(2*x + 5)/cos(x)**2 + 2*tan(x)*cos(2*x + 5))) == 0 and simplify(diff(yy, x) - (sin(2*x + 5)/cos(x)**2 + 2*tan(x)*cos(2*x + 5)))==0)
ok("36.19(5)", simplify(diff(cos(3*x)/(x - 1), x) - (-3*(x - 1)*sin(3*x) - cos(3*x))/(x - 1)**2) == 0)
f = x**2 - 5*x; x1 = solve(diff(f, x) + 1, x)[0]; ok("37.16", expand(f.subs(x, x1) - (x - x1)) == expand(-x - 4))
ok("37.1(5)", cos(pi) + (-sin(pi))*(x - pi) == -1)
r = 6 - 4*sqrt(2); ok("12.5(6)", abs(N(sqrt(3*r - 1) + sqrt(r + 3) - 2)) < 1e-12 and abs(N(sqrt(3*(6 + 4*sqrt(2)) - 1) + sqrt(10 + 4*sqrt(2)) - 2)) > 1)
F = (x - 1)**2*(x + 5)**2; cand = [F.subs(x, v) for v in [-3, 2] + [r for r in solve(diff(F, x), x) if -3 <= r <= 2]]; ok("40.4(3)", (min(cand), max(cand)) == (0, 81))
ok("42.1(8)", solve(Abs(x) + x**2, x) == [0])
g = cos(x) + x*sqrt(3)/2; ok("38.12(3)", solveset(diff(g, x) >= 0, x, I(pi/3, 7*pi/3)) == I(2*pi/3, 7*pi/3) and solveset(diff(g, x) < 0, x, I(pi/3, 7*pi/3)) == I.Ropen(pi/3, 2*pi/3))
f = sqrt(3*x + 2); x1 = solve(diff(f, x) - 1, x); ok("37.10(3)", x1 == [Rational(1, 12)] and f.subs(x, x1[0]) == Rational(3, 2))
ok("37.19", sin(0) == 0 and cos(0) == 1)
Sc = 539*t**3 + (18 - 11*t)**3; tm = [r for r in solve(diff(Sc, t), t) if 0 <= r <= Rational(18, 11)]
ok("40.12", tm == [1] and Sc.subs(t, 1) < min(Sc.subs(t, 0), Sc.subs(t, Rational(18, 11))))
ok("19.16", set(solve(x**4 - Rational(1, 256), x)) == {Rational(1, 4), -Rational(1, 4)})
